contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        vm.assume(_feeRate > 0);
        vm.assume(_feeRate < 10000);

        bool initializedOk;
        try c.initialize(
            address(0),
            address(0),
            0,
            0,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        ) {
            initializedOk = true;
        } catch {
            initializedOk = false;
        }

        if (initializedOk) {
            assertTrue(c.feeRate() <= 5000);
        } else {
            assertTrue(true);
        }
    }
}
